/* Pure production calculations. No browser, network, or storage dependencies. */
(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.QuestEngine=factory();})(typeof globalThis!=='undefined'?globalThis:this,function(){
'use strict';
function validateTimings(steps){if(!Array.isArray(steps)||!steps.length||steps.length>999||steps.some(n=>!Number.isFinite(n)||n<=0))throw new Error('Each step needs a positive duration in minutes.');}
function calculateGoal({start,stepMinutes,productiveMinutes,overtimeMinutes=0,rateMultiplier=1}){validateTimings(stepMinutes);if(!Number.isInteger(start)||start<0||start>stepMinutes.length)throw new Error('Start must be a completed step within the sequence.');if(!Number.isFinite(productiveMinutes)||productiveMinutes<0||!Number.isFinite(overtimeMinutes)||overtimeMinutes<0||!Number.isFinite(rateMultiplier)||rateMultiplier<=0)throw new Error('Time budgets must be nonnegative and the rate must be positive.');let remaining=productiveMinutes+overtimeMinutes,goal=start,used=0;for(let i=start;i<stepMinutes.length;i++){const duration=stepMinutes[i]/rateMultiplier;if(duration>remaining+1e-9)break;remaining-=duration;used+=duration;goal=i+1;}return {goal,availableMinutes:productiveMinutes+overtimeMinutes,usedMinutes:used,remainingMinutes:Math.max(0,remaining),total:stepMinutes.length};}
function summarize(record){const {start,end,goal,total}=record;if(![start,end,goal,total].every(Number.isInteger)||total<1||start<0||end<start||goal<start||end>total||goal>total)throw new Error('Invalid start, end, goal, or total step.');return {gap:end-goal,completion:Math.round(end/total*100),targetCompletion:Math.round(goal/total*100),goalMet:end>=goal,unitComplete:end===total,attainment:goal>start?Math.round((end-start)/(goal-start)*100):null};}
return {calculateGoal,summarize,validateTimings};
});
